import os
from typing import Dict, Any, List
from mindee import Client
from mindee.documents.invoice import InvoiceV4

def validate_structured_extraction(file_path: str, min_confidence: float = 0.85) -> Dict[str, Any]:
    client = Client(api_key=os.environ["MINDEE_API_KEY"])
    with open(file_path, "rb") as f:
        response = client.parse(doc_type=InvoiceV4, input_document=f)

    doc = response.document
    required_fields = {
        "invoice_number": doc.invoice_number,
        "invoice_date": doc.date,
        "total_amount": doc.total_amount,
        "supplier_name": getattr(doc.supplier, "name", None) if doc.supplier else None
    }

    validated_data: Dict[str, Any] = {}
    validation_issues: List[str] = []

    for field_name, field_obj in required_fields.items():
        if field_obj is None:
            validation_issues.append(f"{field_name} is missing")
            continue

        value = getattr(field_obj, "value", None)
        confidence = getattr(field_obj, "confidence", 1.0)

        if value is None or str(value).strip() == "":
            validation_issues.append(f"{field_name} has no value")
        elif confidence < min_confidence:
            validation_issues.append(f"{field_name} confidence {confidence:.3f} is below {min_confidence}")
        else:
            validated_data[field_name] = value

    if validation_issues:
        raise ValueError("Structured field validation failed: " + "; ".join(validation_issues))

    return validated_data
